const mails = await api.get("/mails", { label: "complaint" });
const list = Array.isArray(mails) ? mails : (mails.items || mails.mails || mails.data || []);
console.log(Array.isArray(mails) ? "array" : Object.keys(mails));
if (list.length) console.log(Object.keys(list[0]));
const ids = [...new Set(list.map(m => m.customer_id))];
console.log("mails:", list.length, "unique customers:", ids.length);
const result = [];
for (const id of ids) {
  const c = await api.get(`/customers/${id}`);
  result.push({ customer_id: id, tier: c.tier });
}
return result;

